//! The workbook package of the dc-kt3l cases, generated byte for byte: sheet Inputs holds A1 =
//! 1.5, A2 = 2.25 and A3 = 4; sheet Calc holds a SUM chain, a formula whose cached result is
//! deliberately wrong, a function no catalogue holds and a reader of it (the table in
//! `dc_kt3l.rs`). The acceptance cases and `cargo xtask compare`'s unit tests (`src/compare.rs`)
//! build their workbooks with it.

// Each includer uses part of it.
#![allow(dead_code)]

/// The CRC-32 (IEEE 802.3, reflected) of `data`, bit by bit.
fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFF_FFFFu32;
    for &byte in data {
        crc ^= u32::from(byte);
        for _ in 0..8 {
            crc = if crc & 1 == 1 {
                (crc >> 1) ^ 0xEDB8_8320
            } else {
                crc >> 1
            };
        }
    }
    !crc
}

/// An archive of `entries` (name, content), each stored uncompressed, in the order given.
fn stored_zip(entries: &[(&str, &[u8])]) -> Vec<u8> {
    // DOS date 1980-01-01, time 00:00.
    const DATE: u16 = 0x21;
    let push16 = |out: &mut Vec<u8>, value: u16| out.extend_from_slice(&value.to_le_bytes());
    let push32 = |out: &mut Vec<u8>, value: u32| out.extend_from_slice(&value.to_le_bytes());
    let mut out = Vec::new();
    let mut offsets = Vec::new();
    for (name, content) in entries {
        offsets.push(out.len() as u32);
        push32(&mut out, 0x0403_4b50);
        for field in [20u16, 0, 0, 0, DATE] {
            push16(&mut out, field);
        }
        push32(&mut out, crc32(content));
        push32(&mut out, content.len() as u32);
        push32(&mut out, content.len() as u32);
        push16(&mut out, name.len() as u16);
        push16(&mut out, 0);
        out.extend_from_slice(name.as_bytes());
        out.extend_from_slice(content);
    }
    let directory = out.len();
    for ((name, content), offset) in entries.iter().zip(offsets) {
        push32(&mut out, 0x0201_4b50);
        for field in [20u16, 20, 0, 0, 0, DATE] {
            push16(&mut out, field);
        }
        push32(&mut out, crc32(content));
        push32(&mut out, content.len() as u32);
        push32(&mut out, content.len() as u32);
        for field in [name.len() as u16, 0, 0, 0, 0] {
            push16(&mut out, field);
        }
        push32(&mut out, 0);
        push32(&mut out, offset);
        out.extend_from_slice(name.as_bytes());
    }
    let size = (out.len() - directory) as u32;
    push32(&mut out, 0x0605_4b50);
    for field in [0u16, 0, entries.len() as u16, entries.len() as u16] {
        push16(&mut out, field);
    }
    push32(&mut out, size);
    push32(&mut out, directory as u32);
    push16(&mut out, 0);
    out
}

const MAIN: &str = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
const RELATIONSHIPS: &str = "http://schemas.openxmlformats.org/package/2006/relationships";
const RELATIONSHIP_ATTRIBUTES: &str =
    "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
const OFFICE_DOCUMENT: &str =
    "http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument";
const WORKSHEET: &str =
    "http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet";

/// The Inputs sheet: A1 = 1.5, A2 = 2.25, A3 = 4, and `extra` cells after A3's row.
pub fn inputs_sheet(extra: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="{MAIN}"><sheetData><row r="1"><c r="A1"><v>1.5</v></c></row><row r="2"><c r="A2"><v>2.25</v></c></row><row r="3"><c r="A3"><v>4</v></c></row>{extra}</sheetData></worksheet>"#
    )
}

/// The Calc sheet of the table in `dc_kt3l.rs`, with `extra` cells in row 1 after B1.
pub fn calc_sheet(extra: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="{MAIN}"><sheetData><row r="1"><c r="A1"><f>SUM(Inputs!A1:A3)</f><v>7.75</v></c><c r="B1" t="e"><f>NOSUCHFUNCTION(Inputs!A1)</f><v>#NAME?</v></c>{extra}</row><row r="2"><c r="A2"><f>SUM(A1,Inputs!A1)</f><v>9.25</v></c><c r="B2" t="e"><f>B1*2</f><v>#NAME?</v></c></row><row r="3"><c r="A3"><f>SUM(A1:A2)</f><v>99</v></c></row></sheetData></worksheet>"#
    )
}

/// The package with sheets Inputs (`inputs`) and Calc (`calc`), in that order, and the workbook
/// part's `workbook_pr` (a `workbookPr` element, or nothing) before its sheets.
pub fn package_with(inputs: &str, calc: &str, workbook_pr: &str) -> Vec<u8> {
    let content_types = r#"<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>"#;
    let relationships = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="{RELATIONSHIPS}"><Relationship Id="rId1" Type="{OFFICE_DOCUMENT}" Target="xl/workbook.xml"/></Relationships>"#
    );
    let workbook = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="{MAIN}" xmlns:r="{RELATIONSHIP_ATTRIBUTES}">{workbook_pr}<sheets><sheet name="Inputs" sheetId="1" r:id="rId1"/><sheet name="Calc" sheetId="2" r:id="rId2"/></sheets></workbook>"#
    );
    let workbook_relationships = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="{RELATIONSHIPS}"><Relationship Id="rId1" Type="{WORKSHEET}" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="{WORKSHEET}" Target="worksheets/sheet2.xml"/></Relationships>"#
    );
    stored_zip(&[
        ("[Content_Types].xml", content_types.as_bytes()),
        ("_rels/.rels", relationships.as_bytes()),
        ("xl/workbook.xml", workbook.as_bytes()),
        (
            "xl/_rels/workbook.xml.rels",
            workbook_relationships.as_bytes(),
        ),
        ("xl/worksheets/sheet1.xml", inputs.as_bytes()),
        ("xl/worksheets/sheet2.xml", calc.as_bytes()),
    ])
}

/// The package with sheets Inputs (`inputs`) and Calc (`calc`) and no `workbookPr`.
pub fn package(inputs: &str, calc: &str) -> Vec<u8> {
    package_with(inputs, calc, "")
}

/// The workbook of the table in `dc_kt3l.rs`.
pub fn workbook() -> Vec<u8> {
    package(&inputs_sheet(""), &calc_sheet(""))
}
